import { useEffect, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';
import { EMOJIS, RULES, validName, type Card, type CoinSide, type DuelGame, type DuelView, type Phase, type PlayerView, type RoomView } from '@bluff-house/shared';
import { clearError, enterRoom, getSnapshot, initializeConnection, returnToMenu, sendCommand, subscribe, type ConnectionState } from './connection';

const chips = (value: number) => value.toLocaleString('en-CA');
const suits = { S: '♠', H: '♥', D: '♦', C: '♣' };
const phaseNames: Record<Phase, string> = { LOBBY: 'Private lobby', HOUSE_AUCTION: 'Bid for the House', HOUSE_REVEAL: 'Meet the House', BETTING: 'Place your bets', POT_TWIST: 'Opt into Pot Twist', DEALING: 'Dealing cards', HAND_CHAOS: 'Change the hands', PLAYER_TURN: 'Player turns', BLUFF_OFFER: 'Call My Bluff', BLUFF_REVEAL: 'The reveal', DEALER_TURN: 'Dealer plays', ROUND_RESULT: 'Round settled', SOCIAL: 'Challenge your friends', LAST_STAND_CHOICE: "House's Last Stand", DUEL: 'Duel in progress', DUEL_RESULT: 'Duel settled', WAITING_FOR_PLAYERS: 'Waiting for players', RESULTS: 'The final reckoning' };
const initials = (name: string) => name.trim().split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();

function Brand({ small = false }: { small?: boolean }) {
  return <div className={`brand ${small ? 'brand-small' : ''}`} aria-label="Bluff House"><span className="brand-mark" aria-hidden="true">♠</span><span>BLUFF<span className="brand-house">HOUSE</span></span></div>;
}

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current; dialog?.showModal(); return () => dialog?.close(); }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'modal-wide' : ''}`} onCancel={onClose} aria-labelledby="dialog-title" onClick={event => { if (event.target === event.currentTarget) onClose(); }}>
    <div className="modal-top"><span className="eyebrow">YOU'RE ON THE GUEST LIST</span><button className="icon-button" onClick={onClose} aria-label="Close dialog">×</button></div>
    <h2 id="dialog-title">{title}</h2>{children}
  </dialog>;
}

function HowToPlay({ onClose }: { onClose: () => void }) {
  return <Modal title="Know the table." onClose={onClose} wide>
    <p className="muted">A private Blackjack table for 2–6 friends. All chips are fictional.</p>
    <div className="rules-grid">
      <section><span className="rule-number">01</span><h3>Bring your people</h3><p>Create a room, share its code, and ready up. Everyone starts with 1,000 chips. The host starts when at least two connected players are ready.</p></section>
      <section><span className="rule-number">02</span><h3>Place a little trust</h3><p>Bet 50–250 chips in steps of 50. Edit or withdraw before the timer ends. Skip a wager to sit out that round.</p></section>
      <section><span className="rule-number">03</span><h3>Get close to 21</h3><p>Hit for another card or stand to hold. Face cards count as 10; Aces count as 1 or 11. Going over 21 busts. The dealer stands on all 17s.</p></section>
      <section><span className="rule-number">04</span><h3>Make the chips count</h3><p>A win pays 1:1 profit; an initial Blackjack pays 3:2. Ties return your stake. Classic ends after three rounds. Party uses the host’s three- or six-round preset. The highest final balance wins; equal balances share the crown.</p></section>
      <section><span className="rule-number">05</span><h3>Call My Bluff</h3><p>Once per round, on your turn with a hard total of 12–20, stake 50–250 chips on “My next hit will not bust.” The first rival to match your stake within 8 seconds accepts. One card is drawn immediately: stay at 21 or below and you win the pot; bust and your challenger wins.</p></section>
      <section><span className="rule-number">06</span><h3>Keep your nerve</h3><p>No challenger? Your reserved stake returns and your turn resumes with at least 5 seconds. A challenge winner receives both stakes, for a profit equal to one stake. Stood, busted, and skipped players can still challenge if they have enough chips. Blackjack settles separately.</p></section>
      <section><span className="rule-number">07</span><h3>Party duels</h3><p>Between Party rounds, invite a rival for 50–250 chips each. The defender chooses Rock Paper Scissors, Coin Flip, Connect 4, or Bullet Chess. The first accepted duel commits both stakes. Winners receive the pot; draws refund both stakes. Connect 4 allows 8 seconds per move and 45 seconds total. Chess gives each player 30 seconds with a 60-second total cap. Refreshing never resets a clock.</p></section>
      <section><span className="rule-number">08</span><h3>Change the hands</h3><p>Party Chaos cards are earned at nonfinal settlements by players tied in the bottom two balance positions. Hold up to two cards; use one card or Pot Twist opt-in per round. After dealing, Hand Swap exchanges your eligible hand with a rival; Table Turn moves all eligible hands one seat left. Only one movement can win the five-second window. Connected, funded, unacted two-card hands may move; naturals and dealer cards stay put. Wagers and bluff allowances stay with seats.</p></section>
      <section><span className="rule-number">09</span><h3>Take a Second Chance</h3><p>Use Second Chance only immediately after your latest ordinary Hit leaves your active hand below 21, before your next decision. It replaces that one card from the shoe and gives you a fresh 20-second decision. The discarded card remains consumed and visible. You cannot undo a bust, 21, natural, challenged draw or settled hand; a previous bluff reveal never changes.</p></section>
      <section><span className="rule-number">10</span><h3>Fund a bounty</h3><p>Choose six-round Party for three-win bounty defenses and up to two sequential contests per social interval. During admission, commit 50–250 chips against a rival, up to 1,000 per active bounty. New bounties need at least three social intervals remaining. A bounty challenge matches 50 chips each; the target chooses a game. Three consecutive target wins claim the bounty; a target loss pays 85% to the challenger and the remainder to the Vault. Draws preserve the streak. Each target qualifies once per interval. Unresolved bounty contributions return to their original owners at match end.</p></section>
    </div>
    <p className="rule-note">Your seat follows this browser profile. Refresh to reconnect; use separate browser profiles or devices for different players.</p>
    <button className="button primary full-width" onClick={onClose}>I'm in</button>
  </Modal>;
}

function EntryForm({ mode, onClose, state }: { mode: 'host' | 'join'; onClose: () => void; state: ConnectionState }) {
  const [username, setUsername] = useState('');
  const [code, setCode] = useState('');
  const [validation, setValidation] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const busy = submitting || !!state.pending;
  return <Modal title={mode === 'host' ? 'Your table awaits.' : 'Pull up a chair.'} onClose={onClose}>
    <p className="muted">{mode === 'host' ? 'Create a private room and invite your friends.' : 'Enter the code your host shared with you.'}</p>
    <form onSubmit={async event => {
      event.preventDefault();
      if (!validName(username)) { setValidation('Use 2–16 letters, numbers, spaces, underscores, or hyphens.'); return; }
      if (mode === 'join' && !code.trim()) { setValidation('Enter your room code.'); return; }
      setValidation(null); setSubmitting(true);
      if (await enterRoom(mode, username, code)) onClose();
      setSubmitting(false);
    }}>
      <label htmlFor="username">Guest name</label>
      <input autoFocus id="username" name="username" autoComplete="nickname" placeholder="What should we call you?" value={username} onChange={event => setUsername(event.target.value)} maxLength={16} required disabled={busy} aria-describedby="name-hint" />
      <p id="name-hint" className="field-hint">2–16 characters. Your friends will see this name.</p>
      {mode === 'join' && <><label htmlFor="room-code">Room code</label><input id="room-code" name="roomCode" className="code-input" placeholder="ROOM CODE" value={code} onChange={event => setCode(event.target.value.toUpperCase())} autoCapitalize="characters" autoComplete="off" spellCheck={false} maxLength={8} required disabled={busy} /></>}
      {(validation || state.error) && <div className="form-error" role="alert">{validation || state.error}</div>}
      <button className="button primary full-width" type="submit" disabled={busy}>{busy ? 'Finding your seat…' : mode === 'host' ? 'Create Room' : 'Join Room'}<span aria-hidden="true">↗</span></button>
    </form>
    <p className="fine-print">No account. No real money. Just your best poker face.</p>
  </Modal>;
}

function Menu({ state }: { state: ConnectionState }) {
  const [modal, setModal] = useState<'host' | 'join' | 'rules' | null>(null);
  const blocked = state.status === 'checking' || state.status === 'connecting';
  return <main className="menu-page">
    <header className="menu-header"><Brand small /><span className="header-note"><span className="status-dot" /> PRIVATE TABLES. REAL RIVALRIES.</span></header>
    <section className="menu-hero">
      <div className="hero-copy"><div className="eyebrow"><span className="gold-line" /> THE NIGHT BELONGS TO THE BOLD</div><h1>Good friends.<br /><em>Bad intentions.</em></h1><p className="hero-tagline">Trust Nobody. Call Their Bluff.</p><p className="hero-description">A seat at the table. A stack of chips.<br />A room full of people who swear you can trust them.</p>
        <div className="entry-actions"><button className="button primary" disabled={blocked} onClick={() => { clearError(); setModal('host'); }}>Host Room <span aria-hidden="true">↗</span></button><button className="button secondary" disabled={blocked} onClick={() => { clearError(); setModal('join'); }}>Join Room <span aria-hidden="true">→</span></button></div>
        <button className="text-button how-link" onClick={() => setModal('rules')}><span className="play-circle" aria-hidden="true">?</span> First time at the table? <strong>How to play</strong></button>
      </div>
      <div className="hero-art" aria-hidden="true"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="art-glow" /><div className="art-caption">THE HOUSE ALWAYS REMEMBERS</div><div className="art-card art-card-back"><span>BH</span></div><div className="art-card art-card-queen"><span className="art-card-corner">Q<small>♥</small></span><span className="art-symbol">♥</span><span className="art-card-corner bottom">Q<small>♥</small></span></div><div className="art-card art-card-ace"><span className="art-card-corner">A<small>♠</small></span><span className="art-symbol">♠</span><span className="art-card-corner bottom">A<small>♠</small></span></div><div className="art-chip chip-red"><span>50</span></div><div className="art-chip chip-gold"><span>100</span></div><div className="art-chip chip-black"><span>BH</span></div><span className="art-spark spark-one">✦</span><span className="art-spark spark-two">✦</span></div>
    </section>
    <footer className="menu-footer"><div><span className="footer-symbol">♣</span><span><strong>2–6 PLAYERS</strong>Bring your own rivals</span></div><div><span className="footer-symbol">♦</span><span><strong>FICTIONAL CHIPS</strong>All the stakes. None of the cash.</span></div><div><span className="footer-symbol">♠</span><span><strong>PRIVATE ROOMS</strong>Your code. Your company.</span></div></footer>
    {state.error && !modal && <div className="menu-error" role="alert">{state.error}<button className="text-button" onClick={clearError}>Dismiss</button></div>}
    {modal === 'rules' && <HowToPlay onClose={() => setModal(null)} />}
    {(modal === 'host' || modal === 'join') && <EntryForm mode={modal} onClose={() => setModal(null)} state={state} />}
  </main>;
}

function Avatar({ player, size = '' }: { player: PlayerView; size?: string }) {
  return <span className={`avatar avatar-${player.seat % 6} ${size}`} aria-hidden="true">{initials(player.name)}</span>;
}

function CopyCode({ code }: { code: string }) {
  const [copied, setCopied] = useState(false);
  const [failed, setFailed] = useState(false);
  return <div className="room-code"><span className="eyebrow">ROOM CODE</span><strong>{code}</strong><button className="copy-button" onClick={async () => { try { await navigator.clipboard.writeText(code); setCopied(true); setFailed(false); window.setTimeout(() => setCopied(false), 2000); } catch { setFailed(true); } }} aria-label={`Copy room code ${code}`}>{copied ? '✓ Copied' : 'Copy Code'}</button>{failed && <small role="status">Select and copy the code above.</small>}</div>;
}

function RoomHeader({ room, onLeave }: { room: RoomView; onLeave: () => void }) {
  return <header className="room-header"><Brand small /><div className="room-header-right"><span className="room-label">PRIVATE ROOM <strong>{room.code}</strong></span><span className="live-pill"><span className="status-dot" /> LIVE</span><button className="text-button leave-button" onClick={onLeave}>Leave Room <span aria-hidden="true">↗</span></button></div></header>;
}

function Lobby({ room, disabled }: { room: RoomView; disabled: boolean }) {
  const me = room.players.find(player => player.id === room.viewerId);
  const connected = room.players.filter(player => player.connected && !player.departed);
  const canStart = connected.length >= 2 && connected.every(player => player.ready);
  const host = room.hostId === room.viewerId;
  return <main className="lobby-page"><div className="lobby-intro"><div><span className="eyebrow">THE EVENING STARTS HERE</span><h1>A familiar company.<br /><em>An uncertain outcome.</em></h1><p className="muted">Share your code. Gather your friends. Keep your tells to yourself.</p></div><CopyCode code={room.code} /></div>
    <div className="lobby-columns"><section className="guest-list"><div className="section-heading"><h2>Your table</h2><span>{connected.length} / {RULES.maxPlayers} connected</span></div><div className="lobby-seats">{Array.from({ length: RULES.maxPlayers }, (_, index) => {
      const player = room.players.find(item => item.seat === index && !item.departed);
      return player ? <div className={`lobby-seat ${player.id === room.viewerId ? 'your-seat' : ''}`} key={index}><Avatar player={player} /><div className="guest-info"><strong>{player.name} {player.id === room.viewerId && <small>YOU</small>}</strong><span>{player.id === room.hostId ? '♛ Host' : 'Guest'} <span aria-hidden="true">·</span> {chips(player.balance)} chips</span></div><span className={`ready-label ${player.connected && player.ready ? 'is-ready' : ''}`}>{!player.connected ? 'Disconnected' : player.ready ? '✓ Ready' : 'Not ready'}</span></div> : <div className="lobby-seat empty-seat" key={index}><span className="empty-avatar">+</span><span>Waiting for a rival<span className="empty-sub">Seat {index + 1} is open</span></span></div>;
    })}</div></section>
    <aside className="lobby-aside"><div className="table-note"><span className="eyebrow">TONIGHT'S TABLE</span><h2>{room.mode === 'PARTY' ? 'Party Blackjack' : 'Classic Blackjack'}</h2><div className="mode-controls" role="group" aria-label="Game mode">{(['CLASSIC', 'PARTY'] as const).map(mode => <button key={mode} className={`button ${room.mode === mode ? 'primary' : 'secondary'}`} aria-pressed={room.mode === mode} disabled={disabled || !host} onClick={() => void sendCommand('lobby:mode', { mode })}>{mode === 'CLASSIC' ? 'Classic' : 'Party'}</button>)}</div><p className="field-hint">{host ? 'Changing mode or match length clears all ready statuses.' : 'The host chooses the mode before the match.'}</p>{room.mode === 'PARTY' && <div className="mode-controls round-controls" role="group" aria-label="Party match length">{([3, 6] as const).map(rounds => <button key={rounds} className={`button ${room.roundLimit === rounds ? 'primary' : 'secondary'}`} aria-pressed={room.roundLimit === rounds} disabled={disabled || !host} onClick={() => void sendCommand('lobby:rounds', { rounds })}>{rounds} rounds</button>)}</div>}{room.mode === 'PARTY' && <p className="party-description">Bid for the House before play. The winning bid funds the Vault; the dealer bank pays the House extra commission on rival Blackjack wins. The Vault is shared at match end.</p>}<div className="lobby-rule"><span>Starting stack</span><strong>1,000 <small>chips</small></strong></div><div className="lobby-rule"><span>Match length</span><strong>{room.roundLimit} <small>rounds</small></strong></div><div className="lobby-rule"><span>Blackjack bets</span><strong>50–250</strong></div><div className="lobby-rule"><span>Natural Blackjack</span><strong>Pays 3:2</strong></div><p>Highest final balance takes the crown. Fictional chips only.</p></div><div className="ready-controls"><button className={`button full-width ${me?.ready ? 'secondary' : 'primary'}`} disabled={disabled || !me} onClick={() => void sendCommand('lobby:ready', { ready: !me?.ready })}>{me?.ready ? 'Cancel Ready' : 'Ready Up'}<span aria-hidden="true">{me?.ready ? '✓' : '→'}</span></button>{host && <button className="button primary full-width" disabled={disabled || !canStart} onClick={() => void sendCommand('match:start')}>Start Game <span aria-hidden="true">↗</span></button>}<p className="fine-print">{connected.length < 2 ? 'At least two connected players are needed.' : !canStart ? 'Waiting for everyone to ready up.' : host ? 'Everyone is ready. The table is yours.' : 'Everyone is ready. Waiting for the host to start.'}</p></div></aside></div>
  </main>;
}

export function PlayingCard({ card, small = false }: { card: Card | null; small?: boolean }) {
  if (!card) return <div className={`playing-card card-hidden ${small ? 'card-small' : ''}`} aria-label="Face-down card"><span aria-hidden="true">♠</span></div>;
  return <div className={`playing-card ${card.suit === 'H' || card.suit === 'D' ? 'red-card' : ''} ${small ? 'card-small' : ''}`} aria-label={`${card.rank} of ${{ S: 'spades', H: 'hearts', D: 'diamonds', C: 'clubs' }[card.suit]}`}><span className="card-corner">{card.rank}<small>{suits[card.suit]}</small></span><span className="card-suit" aria-hidden="true">{suits[card.suit]}</span><span className="card-corner card-corner-bottom" aria-hidden="true">{card.rank}<small>{suits[card.suit]}</small></span></div>;
}

export function Countdown({ deadline, now, label }: { deadline: number | null; now: number; label: string }) {
  const seconds = deadline === null ? null : Math.max(0, Math.ceil((deadline - now) / 1000));
  return seconds === null ? null : <span className={`countdown ${seconds <= 5 ? 'countdown-urgent' : ''}`} aria-label={`${label}: ${seconds} seconds`}><span aria-hidden="true">◷</span> {seconds}<small>s</small></span>;
}

function PlayerSeat({ player, room }: { player: PlayerView; room: RoomView }) {
  const active = room.activePlayerId === player.id && room.phase === 'PLAYER_TURN';
  const you = player.id === room.viewerId;
  return <article className={`player-seat ${active ? 'active-seat' : ''} ${you ? 'local-seat' : ''} ${player.departed || !player.connected ? 'absent-seat' : ''}`} aria-label={`${player.name}${you ? ', you' : ''}${active ? ', active turn' : ''}`}>
    <div className="seat-heading"><Avatar player={player} size="avatar-small" /><div><strong>{player.name} {you && <small>YOU</small>} {room.party?.houseId === player.id && <small className="house-crown" aria-label="House">♛ HOUSE</small>}</strong><span>{player.departed ? 'Left the table' : !player.connected ? 'Disconnected' : active ? '● Thinking…' : player.id === room.hostId ? 'Host' : 'At the table'}</span></div><div className="seat-balance">{room.phase === 'HOUSE_AUCTION' && !you ? 'Sealed' : chips(player.balance)}<small>balance</small></div></div>
    <div className="seat-hand">{player.hand.length ? <><div className="cards fan-cards">{player.hand.map(card => <PlayingCard card={card} small key={card.id} />)}</div><span className={`hand-total ${player.value?.bust ? 'total-bust' : ''} ${player.value?.natural ? 'total-blackjack' : ''}`}>{player.value?.bust ? 'BUST' : player.value?.natural ? 'BJ' : player.value?.total}<small>{player.value?.soft && !player.value.natural && !player.value.bust ? 'SOFT' : ''}</small></span></> : <span className="no-hand">{['BETTING', 'POT_TWIST'].includes(room.phase) ? player.wager > 0 ? 'Wager placed' : 'Awaiting wager' : player.status === 'observer' || player.status === 'skipped' ? 'Watching this round' : 'No hand this round'}</span>}</div>
    <div className="seat-bottom"><span>{player.status === 'stood' ? 'Standing' : player.status === 'bust' ? 'Busted' : player.status === 'natural' ? 'Blackjack' : player.status === 'playing' ? 'In play' : player.status === 'won' ? 'Winner' : player.status.replaceAll('_', ' ')}</span>{player.wager > 0 && ['BETTING', 'POT_TWIST'].includes(room.phase) ? <strong><span className="mini-chip" />{chips(player.wager)} Blackjack wager</strong> : player.committed > 0 ? <strong><span className="mini-chip" />{chips(player.committed)} committed</strong> : player.reserved > 0 ? <strong><span className="mini-chip" />{chips(player.reserved)} reserved</strong> : <span>—</span>}</div>
  </article>;
}

function Standings({ room }: { room: RoomView }) {
  const ordered = room.players.filter(player => player.status !== 'observer').sort((a, b) => b.balance - a.balance || a.seat - b.seat);
  return <section className="rail-section standings"><h2><span aria-hidden="true">♛</span> The standings</h2>{ordered.map((player, index) => <div className="standing-row" key={player.id}><span className="standing-rank">{index + 1}</span><Avatar player={player} size="avatar-tiny" /><span className="standing-name">{player.name}{player.id === room.viewerId && <small>YOU</small>}</span><strong>{room.phase === 'HOUSE_AUCTION' && player.id !== room.viewerId ? 'Sealed' : chips(player.balance)}</strong></div>)}</section>;
}

export function EventFeed({ room }: { room: RoomView }) {
  const events = room.events.slice(-7).reverse();
  return <section className="rail-section event-section"><h2>Table talk <span className="live-tiny">LIVE</span></h2><div className="event-feed" aria-live="polite" aria-relevant="additions">{events.length ? events.map(event => <div className={`table-event event-${event.kind}`} key={event.id}><span className="event-dot" /><p>{event.text}</p></div>) : <p className="muted">The night is just getting started.</p>}</div></section>;
}

function BluffControls({ room, me, disabled }: { room: RoomView; me?: PlayerView; disabled: boolean }) {
  const [stake, setStake] = useState(100);
  const eligible = !!me?.value && !me.value.soft && me.value.total >= 12 && me.value.total <= 20 && !me.bluffUsed;
  const amount = me && me.available < stake && me.available >= 50 ? Math.floor(me.available / 50) * 50 : stake;
  return <div className="bluff-controls"><div><strong>My next hit will not bust.</strong><p>{me?.bluffUsed ? 'You have used your one offer this round.' : !eligible ? 'Offer once per round with a hard total of 12–20.' : 'Stake chips and give your rivals 8 seconds to call you.'}</p></div><div className="bluff-stakes" role="group" aria-label="Choose your bluff stake">{[50, 100, 150, 200, 250].map(value => <button className={`bet-chip ${amount === value ? 'selected-chip' : ''}`} key={value} disabled={disabled || !eligible || value > (me?.available ?? 0)} aria-label={`Bluff ${value} chips`} aria-pressed={amount === value} onClick={() => setStake(value)}>{value}</button>)}</div><button className="button bluff-button" disabled={disabled || !eligible || amount > (me?.available ?? 0)} onClick={() => void sendCommand('bluff:offer', { claimType: 'NEXT_HIT_SAFE', amount })}>Call My Bluff <span>{chips(amount)}</span></button>{eligible && (me?.available ?? 0) < 50 && <p className="field-hint">You need 50 available chips to offer.</p>}</div>;
}

function BluffEvent({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const bluff = room.bluff;
  if (!bluff || !['BLUFF_OFFER', 'BLUFF_REVEAL'].includes(room.phase)) return null;
  const me = room.players.find(player => player.id === room.viewerId);
  const claimant = room.players.find(player => player.id === bluff.claimantId);
  const winner = room.players.find(player => player.id === bluff.winnerId);
  const own = bluff.claimantId === room.viewerId;
  const open = room.phase === 'BLUFF_OFFER' && bluff.status === 'open';
  const canAccept = !!me && !own && me.connected && !me.departed && me.status !== 'observer' && me.available >= bluff.amount;
  return <section className={`bluff-event ${open ? 'bluff-open' : 'bluff-revealed'}`} aria-label={open ? 'Bluff challenge' : 'Bluff result'} aria-live="polite"><div className="bluff-event-heading"><span className="eyebrow">{open ? 'A CHALLENGE ON THE TABLE' : 'THE BLUFF IS SETTLED'}</span>{open && <Countdown deadline={bluff.deadline} now={now} label="Challenge closes" />}</div><h2>{open ? `${claimant?.name ?? 'A player'} says…` : `${winner?.name ?? 'The winner'} takes the pot.`}</h2>{open ? <><blockquote>“My next hit will not bust.”</blockquote><p><strong>{chips(bluff.amount)} chips</strong> each · <strong>{chips(bluff.amount * 2)} chip pot</strong>. The first funded challenger gets the call.</p>{own ? <p>Your stake is reserved. Waiting for a rival to accept.</p> : <button className="button primary" disabled={disabled || !canAccept || now >= bluff.deadline} onClick={() => void sendCommand('bluff:accept')}>Accept Challenge <span>{chips(bluff.amount)}</span></button>}{!own && !canAccept && <p className="field-hint">You need an active match seat and {chips(bluff.amount)} available chips to challenge.</p>}</> : <div className="bluff-reveal-content">{bluff.card && <PlayingCard card={bluff.card} small />}<div><p>{claimant?.name ?? 'The claimant'} {bluff.winnerId === bluff.claimantId ? 'stayed safe.' : 'busted.'}</p><p><strong>{chips(bluff.pot ?? bluff.amount * 2)} chips paid</strong> · {chips(bluff.amount)} chip profit.</p><p className="field-hint">Both stakes are settled. Blackjack continues after the reveal.</p></div></div>}</section>;
}

function Reactions({ state, disabled }: { state: ConnectionState; disabled: boolean }) {
  const [cooling, setCooling] = useState(false);
  const cooldown = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => { if (cooldown.current) clearTimeout(cooldown.current); }, []);
  return <section className="reactions" aria-label="Table reactions"><div className="reaction-buttons" role="group" aria-label="Send a reaction">{EMOJIS.map(emoji => <button className="reaction-button" key={emoji} aria-label={`React ${emoji}`} disabled={disabled || cooling} onClick={() => { setCooling(true); cooldown.current = setTimeout(() => setCooling(false), 1000); void sendCommand('reaction:send', { emoji }); }}>{emoji}</button>)}</div><div className="reaction-stream" aria-live="polite" aria-relevant="additions">{state.reactions.slice(-4).map(event => <span className="reaction-bubble" key={event.id}>{event.text}</span>)}</div></section>;
}

export function ActionPanel({ room, me, disabled, now }: { room: RoomView; me?: PlayerView; disabled: boolean; now: number }) {
  const [amount, setAmount] = useState(100);
  useEffect(() => { setAmount(100); }, [room.bettingId]);
  const canBet = !!me && !me.departed && me.status !== 'observer' && me.available + me.reserved >= 50;
  const betting = room.phase === 'BETTING';
  const yourTurn = room.phase === 'PLAYER_TURN' && room.activePlayerId === room.viewerId;
  const deadlinePassed = room.deadline !== null && now >= room.deadline;
  const activeName = room.players.find(player => player.id === room.activePlayerId)?.name;
  return <section className={`action-panel ${yourTurn ? 'your-turn-panel' : ''}`} aria-label="Your game controls"><div className="your-bank"><span className="eyebrow">YOUR AVAILABLE CHIPS</span><strong><span className="mini-chip" />{chips(me?.available ?? 0)}</strong><div className="bank-details"><span>Balance <b>{chips(me?.balance ?? 0)}</b></span><span>Reserved <b>{chips(me?.reserved ?? 0)}</b></span><span>Committed <b>{chips(me?.committed ?? 0)}</b></span>{!!me?.wager && <span>Blackjack wager <b>{chips(me.wager)}</b></span>}</div></div><div className="action-content">
    {betting ? <><div className="action-label"><strong>{canBet ? me?.reserved ? 'Your wager is reserved.' : 'What are you willing to risk?' : 'Watching this round'}</strong><span>{canBet ? 'Submit before betting closes' : 'You need 50 available chips to place a wager.'}</span></div>{canBet && <div className="bet-controls"><div className="bet-chips" role="group" aria-label="Choose your wager">{[50, 100, 150, 200, 250].map(value => <button className={`bet-chip ${amount === value ? 'selected-chip' : ''}`} key={value} disabled={disabled || deadlinePassed || value > (me?.available ?? 0) + (me?.reserved ?? 0)} onClick={() => setAmount(value)} aria-pressed={amount === value} aria-label={`Bet ${value} chips`}>{value}</button>)}</div><button className="button primary" disabled={disabled || deadlinePassed || amount > (me?.available ?? 0) + (me?.reserved ?? 0)} onClick={() => void sendCommand('bet:submit', { amount })}>{me?.reserved ? 'Update Bet' : 'Place Bet'}<span>{chips(amount)}</span></button>{!!me?.reserved && <button className="text-button withdraw-button" disabled={disabled || deadlinePassed} onClick={() => void sendCommand('bet:withdraw')}>Withdraw</button>}</div>}</> : yourTurn ? <><div className="action-label"><strong>Your move, {me?.name}.</strong><span>Hit for a card or stand with your hand.</span></div><div className="turn-controls"><button className="button primary" disabled={disabled || deadlinePassed} onClick={() => void sendCommand('turn:hit')}>Hit <span aria-hidden="true">+</span></button><button className="button secondary" disabled={disabled || deadlinePassed} onClick={() => void sendCommand('turn:stand')}>Stand <span aria-hidden="true">■</span></button></div><BluffControls room={room} me={me} disabled={disabled || deadlinePassed} /></> : <div className="waiting-action"><span className="waiting-symbol" aria-hidden="true">♠</span><div><strong>{room.phase === 'PLAYER_TURN' ? `${activeName || 'A player'} is making their move.` : room.phase === 'ROUND_RESULT' ? 'The chips have spoken.' : room.phase === 'DEALER_TURN' ? 'Let the dealer do the talking.' : room.phase === 'WAITING_FOR_PLAYERS' ? 'Keeping your table open.' : 'Watch the table.'}</strong><span>{room.phase === 'ROUND_RESULT' ? 'The next round follows shortly.' : room.phase === 'WAITING_FOR_PLAYERS' ? 'Waiting for enough players to reconnect.' : room.phase === 'PLAYER_TURN' ? 'All hands are public. Keep an eye on the competition.' : phaseNames[room.phase]}</span></div></div>}
  </div></section>;
}

function HouseAuction({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const [bid, setBid] = useState(100);
  const auction = room.party?.auction;
  const mine = auction?.bids.find(item => item.playerId === room.viewerId);
  useEffect(() => { setBid(mine?.amount || 100); }, [auction?.id, mine?.amount]);
  if (!auction || !['HOUSE_AUCTION', 'HOUSE_REVEAL'].includes(room.phase)) return null;
  const open = auction.status === 'open';
  const locked = disabled || !open || now >= auction.deadline;
  const winner = room.players.find(player => player.id === auction.winnerId);
  return <section className="house-auction" aria-label="House auction"><span className="eyebrow">THE CROWN HAS A PRICE</span><h2>{open ? 'A sealed bid. An open rivalry.' : winner ? `${winner.name} is the House.` : 'No House this match.'}</h2><p>{open ? 'Bid 50–300 chips or pass. Only you can see your amount until the auction closes. The winning bid goes to the Vault; losing bids return in full.' : winner ? `${chips(auction.winningBid ?? 0)} chips paid into the Vault. The House plays normally; the neutral dealer still deals every card.` : 'Everyone passed. Blackjack continues without House commissions.'}</p><div className="auction-bids">{auction.bids.map(item => <div className="auction-bid" key={item.playerId}><strong>{room.players.find(player => player.id === item.playerId)?.name}{item.playerId === room.viewerId && <small>YOU</small>}</strong><span>{item.amount !== undefined ? item.amount === 0 ? 'Passed' : `${chips(item.amount)} chips` : item.submitted ? 'Bid sealed' : 'Not submitted'}</span></div>)}</div>{open && <><div className="auction-own" role="status">Your bid: <strong>{mine?.submitted ? mine.amount ? `${chips(mine.amount)} chips reserved` : 'Pass' : 'Not submitted — defaults to pass'}</strong></div><div className="bet-controls"><div className="bet-chips" role="group" aria-label="Choose your House bid">{[50, 100, 150, 200, 250, 300].map(amount => <button className={`bet-chip ${bid === amount ? 'selected-chip' : ''}`} key={amount} aria-label={`House bid ${amount} chips`} aria-pressed={bid === amount} disabled={locked} onClick={() => setBid(amount)}>{amount}</button>)}</div><button className="button primary" disabled={locked} onClick={() => void sendCommand('house:bid', { amount: bid })}>{mine?.submitted ? 'Update House Bid' : 'Submit House Bid'}<span>{bid}</span></button><button className="button secondary" disabled={locked} onClick={() => void sendCommand('house:bid', { amount: 0 })}>{mine?.amount ? 'Withdraw and Pass' : 'Pass Auction'}</button></div><p className="field-hint">Bids remain binding if you disconnect. Equal highest bids use a random draw. The auction always closes at its deadline.</p></>}</section>;
}

function DuelStats({ room }: { room: RoomView }) {
  const stats = room.party?.duelStats;
  if (!stats?.some(item => item.wins + item.losses + item.draws > 0)) return null;
  return <section className="duel-stats" aria-label="Duel statistics"><h2>Rivalries, on record.</h2><p className="field-hint">Wins / losses / draws</p>{stats.map(item => <div className="payout-row" key={item.playerId}><strong>{room.players.find(player => player.id === item.playerId)?.name}</strong><span>{item.wins} / {item.losses} / {item.draws}</span></div>)}</section>;
}

const pieceNames: Record<string, string> = { p: 'pawn', n: 'knight', b: 'bishop', r: 'rook', q: 'queen', k: 'king' };
const pieceSymbols: Record<string, string> = { wp: '♙', wn: '♘', wb: '♗', wr: '♖', wq: '♕', wk: '♔', bp: '♟', bn: '♞', bb: '♝', br: '♜', bq: '♛', bk: '♚' };

function BoardDuel({ duel, room, disabled, now }: { duel: DuelView; room: RoomView; disabled: boolean; now: number }) {
  const [selected, setSelected] = useState<string | null>(null);
  const [promotion, setPromotion] = useState('q');
  const playing = duel.status === 'playing';
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Player';
  const c4 = duel.connect4;
  const chess = duel.chess;
  if (c4) {
    const ownTurn = playing && c4.activePlayerId === room.viewerId;
    return <div className="board-duel"><p className="board-turn" role="status">{playing ? `${name(c4.activePlayerId)} to drop a disc.` : 'Connect 4 complete.'}</p><p className="field-hint">Connect four discs vertically, horizontally, or diagonally. Each move has 8 seconds; a missed move forfeits. The 45-second total limit draws an unfinished board.</p><div className="board-legend">{[c4.firstPlayerId, [duel.inviterId, duel.defenderId].find(id => id !== c4.firstPlayerId)!].map((id, index) => <span key={id}><i className={`disc disc-${index + 1}`} />{name(id)}{id === room.viewerId ? ' (you)' : ''}</span>)}</div><div className="connect4-wrap"><div className="connect4-drops" role="group" aria-label="Drop a disc">{Array.from({ length: 7 }, (_, column) => <button key={column} aria-label={`Drop in column ${column + 1}`} disabled={disabled || !ownTurn || !!c4.cells[0][column] || now >= duel.deadline || now >= duel.hardDeadline} onClick={() => void sendCommand('duel:move', { column })}>{column + 1}<span aria-hidden="true">↓</span></button>)}</div><div className="connect4-board" role="grid" aria-label="Connect 4 board">{c4.cells.map((row, rowIndex) => <div className="connect4-row" role="row" key={rowIndex}>{row.map((id, column) => <div key={column} role="gridcell" aria-label={`Row ${rowIndex + 1}, column ${column + 1}: ${id ? name(id) : 'empty'}`}><span className={`disc ${id ? id === c4.firstPlayerId ? 'disc-1' : 'disc-2' : 'disc-empty'}`} /></div>)}</div>)}</div></div>{!ownTurn && playing && <p className="field-hint">{[duel.inviterId, duel.defenderId].includes(room.viewerId) ? 'Wait for your turn.' : 'You are watching this duel.'}</p>}</div>;
  }
  if (!chess) return null;
  const ownColor = room.viewerId === chess.whiteId ? 'w' : room.viewerId === chess.blackId ? 'b' : null;
  const ownTurn = playing && chess.turnId === room.viewerId;
  const moves = chess.legalMoves.filter(move => move.from === selected);
  const moveTo = (to: string) => {
    const choices = moves.filter(move => move.to === to);
    const choice = choices.find(move => move.promotion === promotion) ?? choices.find(move => !move.promotion);
    if (choice) { void sendCommand('duel:move', { from: choice.from, to: choice.to, ...(choice.promotion ? { promotion: choice.promotion } : {}) }); setSelected(null); }
  };
  return <div className="board-duel"><div className="chess-clocks" aria-label="Chess clocks">{[chess.whiteId, chess.blackId].map((id, index) => {
    const remaining = Math.max(0, (chess.remainingMs[id] ?? 0) - (playing && chess.turnId === id ? Math.max(0, now - chess.clockStartedAt) : 0));
    return <div key={id} className={playing && chess.turnId === id ? 'running-clock' : ''}><span>{index === 0 ? 'White' : 'Black'} · {name(id)}</span><strong aria-label={`${name(id)} chess clock: ${Math.ceil(remaining / 1000)} seconds`}>{(remaining / 1000).toFixed(1)}s</strong></div>;
  })}</div><p className="board-turn" role="status">{playing ? `${name(chess.turnId)} to move${chess.check ? ' — CHECK' : ''}.` : 'Chess complete.'}</p><p className="field-hint">30 seconds per player, no increment; 60 seconds total. Select your piece, then a highlighted legal destination. Promotion uses your selected piece. Checkmate, legal draws, resignation, and flag fall settle {duel.purpose === 'LAST_STAND' ? 'the House crown' : 'the pot'}.</p>{ownColor && <label className="chess-promotion" htmlFor="chess-promotion">Promote pawn to<select id="chess-promotion" value={promotion} disabled={disabled || !ownTurn} onChange={event => setPromotion(event.target.value)}><option value="q">Queen</option><option value="r">Rook</option><option value="b">Bishop</option><option value="n">Knight</option></select></label>}<div className="chess-board" role="grid" aria-label="Chess board">{Array.from({ length: 8 }, (_, row) => <div role="row" className="chess-rank" key={row}>{Array.from({ length: 8 }, (_, column) => {
    const square = `${'abcdefgh'[column]}${8 - row}`;
    const piece = chess.board.find(item => item.square === square);
    const destination = moves.some(move => move.to === square);
    const canSelect = piece?.color === ownColor && chess.legalMoves.some(move => move.from === square);
    const label = `${square}: ${piece ? `${piece.color === 'w' ? 'white' : 'black'} ${pieceNames[piece.piece]}` : 'empty'}`;
    const lastMove = chess.lastMove && [chess.lastMove.from, chess.lastMove.to].includes(square);
    return <div role="gridcell" key={square}><button className={`chess-square ${(row + column) % 2 ? 'dark-square' : 'light-square'} ${selected === square ? 'selected-square' : ''} ${destination ? 'legal-square' : ''} ${lastMove ? 'last-move-square' : ''}`} aria-label={label} aria-pressed={selected === square} disabled={disabled || !ownTurn || now >= duel.deadline || now >= duel.hardDeadline || (!canSelect && !destination)} onClick={() => { if (destination) moveTo(square); else setSelected(selected === square ? null : square); }}><span aria-hidden="true" className={piece?.color === 'w' ? 'white-piece' : 'black-piece'}>{piece ? pieceSymbols[`${piece.color}${piece.piece}`] : destination ? '·' : ''}</span><small aria-hidden="true">{square}</small></button></div>;
  })}</div>)}</div><p className="field-hint">{ownTurn ? selected ? `${selected} selected. Choose a highlighted destination.` : 'Your turn. Select a piece to see its legal moves.' : playing ? ownColor ? 'Wait for your turn.' : 'You are watching. White is shown at the bottom.' : 'Both clocks have stopped.'}</p><details className="chess-time-rules"><summary>Chess draws and time rules</summary><p>Checkmate wins. Stalemate, threefold repetition, the fifty-move rule, and insufficient material draw automatically. An unfinished position at 60 seconds also draws.</p><p>Running out of time loses unless the opponent lacks mating material. A bare king cannot win on time. A pawn, rook, queen, two knights, or mixed minor pieces can. A lone knight needs opposing material other than only queens. A side with only bishops needs bishops on both square colors across the board, or a pawn or knight somewhere on the board. This material rule does not evaluate fortresses.</p></details></div>;
}

function HouseBallot({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const [game, setGame] = useState<DuelGame>('RPS');
  const [coinSide, setCoinSide] = useState<CoinSide>('HEADS');
  const party = room.party;
  const social = party?.social;
  if (!party || !social || !party.houseId) return null;
  const ballot = social.ballot;
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Player';
  const me = room.players.find(player => player.id === room.viewerId);
  const house = room.viewerId === party.houseId;
  const canOpen = room.phase === 'SOCIAL' && !ballot && !social.duel && !house && room.round > party.houseSinceRound && !!me?.connected && !me.departed && me.status !== 'observer' && now < social.admissionDeadline;
  if (!ballot) return canOpen ? <section className="house-ballot" aria-label="House overthrow"><span className="eyebrow">THE CROWN CAN CHANGE HANDS</span><h3>Challenge the House's reign.</h3><p>Open a 10-second ballot. At least 75% of the eligible non-House players must vote yes. Opening the ballot does not cast your vote. If it passes, a connected yes voter faces the House in a duel for the crown.</p><button className="button secondary" disabled={disabled} onClick={() => void sendCommand('house:ballot')}>Open Overthrow Ballot</button></section> : null;
  const mine = ballot.votes.find(vote => vote.playerId === room.viewerId);
  const yes = ballot.votes.filter(vote => vote.yes).length;
  const voter = ballot.eligibleVoterIds.includes(room.viewerId);
  return <section className="house-ballot" aria-label="House overthrow"><div className="duel-heading"><span className="eyebrow">HOUSE'S LAST STAND</span>{ballot.status === 'open' && <Countdown deadline={ballot.deadline} now={now} label="Ballot closes" />}{ballot.status === 'selecting' && <Countdown deadline={room.deadline} now={now} label="House game choice closes" />}</div><h3>{ballot.status === 'open' ? `Overthrow ${name(ballot.houseId)}?` : ballot.status === 'selecting' ? 'The vote passed. The House chooses.' : ballot.status === 'playing' ? 'The crown is at stake.' : ballot.status === 'failed' ? 'The overthrow ballot failed.' : party.houseId !== ballot.houseId ? `${name(party.houseId)} takes the House crown.` : `${name(ballot.houseId)} keeps the House crown.`}</h3><p className="ballot-tally" role="status">{yes} / {ballot.requiredVotes} yes votes required · {ballot.eligibleVoterIds.length} eligible voters</p><div className="ballot-voters">{ballot.eligibleVoterIds.map(id => { const vote = ballot.votes.find(item => item.playerId === id); return <span key={id}>{name(id)}: <strong>{vote ? vote.yes ? 'Yes' : 'No' : 'Not voted'}</strong></span>; })}</div>{ballot.status === 'open' && <>{voter ? mine ? <p className="field-hint">Your {mine.yes ? 'yes' : 'no'} vote is locked.</p> : <div className="ballot-actions"><button className="button primary" disabled={disabled || now >= ballot.deadline} onClick={() => void sendCommand('house:vote', { yes: true })}>Vote Yes</button><button className="button secondary" disabled={disabled || now >= ballot.deadline} onClick={() => void sendCommand('house:vote', { yes: false })}>Vote No</button></div> : <p className="field-hint">{room.viewerId === ballot.houseId ? 'The House cannot vote in this ballot.' : 'You were not eligible when this ballot opened.'}</p>}<p className="field-hint">One vote per eligible player. The voter list stays fixed if someone disconnects. The first accepted duel cancels the ballot; a passing ballot cancels pending invitations.</p></>}{ballot.challengerId && <p>Challenger: <strong>{name(ballot.challengerId)}</strong> · defending House: <strong>{name(ballot.houseId)}</strong></p>}{ballot.status === 'selecting' && <>{room.viewerId === ballot.houseId ? <div className="duel-selection"><label htmlFor="last-stand-game">Last Stand game<select id="last-stand-game" value={game} disabled={disabled || (room.deadline !== null && now >= room.deadline)} onChange={event => setGame(event.target.value as DuelGame)}><option value="RPS">Rock Paper Scissors</option><option value="COIN">Coin Flip</option><option value="CONNECT4">Connect 4</option><option value="CHESS">Bullet Chess</option></select></label>{game === 'COIN' && <label htmlFor="last-stand-side">Your Last Stand coin side<select id="last-stand-side" value={coinSide} disabled={disabled} onChange={event => setCoinSide(event.target.value as CoinSide)}><option value="HEADS">Heads</option><option value="TAILS">Tails</option></select></label>}<button className="button primary" disabled={disabled || (room.deadline !== null && now >= room.deadline)} onClick={() => void sendCommand('house:choose', { game, ...(game === 'COIN' ? { coinSide } : {}) })}>Begin Last Stand</button></div> : <p className="field-hint">Waiting for the House to choose a game. If the choice expires, the challenger takes the crown and Blackjack resumes.</p>}<p className="field-hint">No chip stakes. Choose within 8 seconds or forfeit the crown. The challenger must win the duel to take the crown; a draw defends it. Room host permissions do not change.</p></>}{(ballot.status === 'failed' || ballot.status === 'settled') && <p className="field-hint">{ballot.reason?.replaceAll('_', ' ')}{ballot.status === 'failed' ? ' The original invitation window continues; another ballot cannot open this interval.' : ' Crown settlement is final. Blackjack resumes after this result.'}</p>}</section>;
}

function OverthrowHistory({ room }: { room: RoomView }) {
  if (!room.party?.overthrowHistory.length) return null;
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Player';
  return <section className="overthrow-history" aria-label="House role history"><h2>The crown's history.</h2>{room.party.overthrowHistory.map(ballot => <div key={ballot.id}><strong>{name(ballot.houseId)} defending{ballot.challengerId ? ` against ${name(ballot.challengerId)}` : ''}</strong><span>{ballot.winnerId && ballot.winnerId !== ballot.houseId ? `${name(ballot.winnerId)} took the crown` : ballot.status === 'failed' ? 'Ballot failed' : `${name(ballot.houseId)} retained the crown`}</span><small>{ballot.reason?.replaceAll('_', ' ')}</small></div>)}</section>;
}

function BountyBoard({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const [target, setTarget] = useState('');
  const [amount, setAmount] = useState(100);
  const party = room.party;
  if (!party || room.round === 0) return null;
  const me = room.players.find(player => player.id === room.viewerId);
  const social = party.social;
  const admission = room.phase === 'SOCIAL' && !!social && now < social.admissionDeadline;
  const eligible = !!me && me.connected && !me.departed && me.status !== 'observer';
  const rivals = room.players.filter(player => player.id !== room.viewerId && player.connected && !player.departed && player.status !== 'observer');
  const targetId = rivals.some(player => player.id === target) ? target : rivals[0]?.id ?? '';
  const active = party.bounties.find(bounty => bounty.targetId === targetId && bounty.status === 'active');
  const frozen = !!active && social?.duel?.id === active.duelId && social?.duel?.status === 'playing';
  const creationAllowed = !!active || party.bountyOpportunities >= 3;
  const full = !!active && active.total + amount > 1000;
  const pending = social?.invites.some(invite => invite.inviterId === room.viewerId && invite.status === 'pending');
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Original participant';
  const reason = !admission ? 'Fund or challenge bounties during social admission.' : !eligible ? 'Only connected match participants can fund a bounty.' : !targetId ? 'A different connected participant is needed.' : !creationAllowed ? 'New bounties need at least 3 remaining social intervals. Existing active bounties may still receive contributions.' : frozen ? 'This bounty is locked while its accepted defense plays.' : full ? 'A target bounty cannot exceed 1,000 chips.' : amount > (me?.available ?? 0) ? 'You need enough available chips to commit this contribution.' : 'Contributions commit immediately and remain owned by their contributors until settlement.';
  const canFund = admission && eligible && !!targetId && creationAllowed && !frozen && !full && amount <= (me?.available ?? 0);
  return <section className="bounty-board" aria-label="Bounty board"><div className="duel-heading"><span className="eyebrow">PUT A PRICE ON A RIVAL</span><span className="bounty-opportunities">{party.bountyOpportunities} social intervals remain</span></div><h2>The bounty board.</h2><p>Three consecutive qualifying defense wins claim the full bounty. A target loss pays 85% to the challenger and the exact remainder to the Vault. Draws leave the streak unchanged. Each target can defend once per interval, including its second slot.</p>
    {room.phase !== 'RESULTS' && <div className="bounty-funding"><label htmlFor="bounty-target">Bounty target<select id="bounty-target" value={targetId} disabled={disabled || !admission || !eligible} onChange={event => setTarget(event.target.value)}>{rivals.length ? rivals.map(player => <option value={player.id} key={player.id}>{player.name}</option>) : <option value="">No eligible rival</option>}</select></label><div className="bet-chips" role="group" aria-label="Bounty contribution">{[50, 100, 150, 200, 250].map(stake => <button key={stake} className={`bet-chip ${amount === stake ? 'selected-chip' : ''}`} aria-label={`Bounty contribution ${stake} chips`} aria-pressed={amount === stake} disabled={disabled || !admission || !eligible || stake > (me?.available ?? 0)} onClick={() => setAmount(stake)}>{stake}</button>)}</div><button className="button primary" disabled={disabled || !canFund} onClick={() => void sendCommand('bounty:contribute', { targetId, amount })}>Fund Bounty <span>{chips(amount)}</span></button><p className="field-hint bounty-funding-reason" role="status">{reason}</p></div>}
    <div className="bounty-list">{party.bounties.map(bounty => {
      const targetPlayer = room.players.find(player => player.id === bounty.targetId);
      const locked = social?.duel?.id === bounty.duelId && social?.duel?.status === 'playing';
      const defended = !!social && party.bounties.some(item => item.targetId === bounty.targetId && item.defendedIntervalIds.includes(social.id));
      const myContribution = bounty.contributions.filter(item => item.playerId === room.viewerId).reduce((sum, item) => sum + item.amount, 0);
      const inviteReason = !admission ? 'Wait for social admission.' : bounty.status !== 'active' ? 'This bounty has settled.' : bounty.targetId === room.viewerId ? 'Rivals challenge your bounty.' : defended ? 'This target has already defended in this interval.' : pending ? 'Resolve your current outgoing invitation first.' : !targetPlayer?.connected || targetPlayer.departed ? 'The target must reconnect before a new invitation.' : (me?.available ?? 0) < 50 || (targetPlayer?.balance ?? 0) < 50 ? 'Both players need 50 available chips for the matched duel.' : 'Challenge with 50 chips each; the target chooses the game.';
      const canInvite = admission && eligible && bounty.status === 'active' && bounty.targetId !== room.viewerId && !defended && !pending && !!targetPlayer?.connected && !targetPlayer.departed && (me?.available ?? 0) >= 50 && targetPlayer.balance >= 50;
      return <article className={`bounty-card bounty-${bounty.status}`} key={bounty.id} aria-label={`Bounty on ${name(bounty.targetId)}`}><div className="duel-heading"><h3>{name(bounty.targetId)}</h3><span className="bounty-status">{bounty.status}</span></div><strong className="bounty-pot">{chips(bounty.total)} chips</strong><p className="bounty-streak">Defense streak: <strong>{bounty.streak} / 3</strong> · {bounty.defendedIntervalIds.length} qualifying defenses</p><p className="field-hint">Your committed contributions: {chips(myContribution)} chips.{locked ? ' Funding is frozen during this defense.' : ''}</p><div className="bounty-contributions" aria-label={`Contributors to ${name(bounty.targetId)} bounty`}>{bounty.contributions.map(item => <div key={item.id}><span>{name(item.playerId)}{item.playerId === room.viewerId ? ' (you)' : ''}</span><strong>{chips(item.amount)} chips</strong></div>)}</div>{bounty.status === 'active' && room.phase !== 'RESULTS' ? <><button className="button secondary" disabled={disabled || !canInvite} onClick={() => void sendCommand('bounty:invite', { bountyId: bounty.id })}>Challenge {name(bounty.targetId)}'s bounty</button><p className="field-hint">{inviteReason}</p></> : <p className="bounty-settlement" role="status">{bounty.status === 'claimed' ? `${name(bounty.targetId)} claimed all ${chips(bounty.total)} chips after three wins.` : bounty.status === 'defeated' ? `${name(bounty.winnerId ?? '')} received ${chips(Math.floor(85 * bounty.total / 100))} chips; ${chips(bounty.total - Math.floor(85 * bounty.total / 100))} chips funded the Vault.` : 'Unclaimed contributions returned to their original contributors before final rankings.'}</p>}</article>;
    })}</div>{!party.bounties.length && <p className="field-hint">No bounties funded yet. Six-round Party allows enough intervals for a three-win defense streak.</p>}<p className="field-hint">Bounty escrow is separate from your personal available chips and the matched duel pot. Contributions cannot be cancelled or redirected. Unresolved contributions are refunded at match end; bounty payouts receive no House commission.</p></section>;
}

function SocialDuel({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const [target, setTarget] = useState('');
  const [amount, setAmount] = useState(100);
  const [game, setGame] = useState<DuelGame>('RPS');
  const [coinSide, setCoinSide] = useState<CoinSide>('HEADS');
  const social = room.party?.social;
  const me = room.players.find(player => player.id === room.viewerId);
  const rivals = room.players.filter(player => player.id !== room.viewerId && player.connected && !player.departed && player.status !== 'observer');
  const defenderId = rivals.some(player => player.id === target) ? target : rivals[0]?.id ?? '';
  if (!social || !['SOCIAL', 'LAST_STAND_CHOICE', 'DUEL', 'DUEL_RESULT'].includes(room.phase)) return null;
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Player';
  const duel = social.duel;
  const outgoing = social.invites.find(invite => invite.inviterId === room.viewerId && invite.status === 'pending');
  const incoming = social.invites.filter(invite => invite.defenderId === room.viewerId && invite.status === 'pending');
  const eligible = !!me && me.connected && !me.departed && me.status !== 'observer';
  const admissionClosed = now >= social.admissionDeadline;
  const acceptanceFunds = (me?.available ?? 0) + (outgoing?.amount ?? 0);
  const participant = duel && [duel.inviterId, duel.defenderId].includes(room.viewerId);
  const playing = duel?.status === 'playing';
  const ballotBlocksInvites = !!social.ballot && ['selecting', 'playing', 'settled'].includes(social.ballot.status);
  return <section className="social-duel" aria-label="Party duel">
    <HouseBallot room={room} disabled={disabled} now={now} />
    <div className="social-slot-budget" aria-label="Social interval budget"><span>Contest slot {social.slot} / {room.roundLimit === 6 ? 2 : 1}</span><span>Whole interval limit</span><Countdown deadline={social.hardDeadline} now={now} label="Social interval hard limit" /></div><div className="duel-heading"><span className="eyebrow">A LITTLE FRIENDLY COMPETITION</span><Countdown deadline={playing ? duel.deadline : room.phase === 'SOCIAL' ? social.admissionDeadline : room.deadline} now={now} label={playing ? duel.game === 'RPS' ? 'Throw closes' : duel.game === 'CONNECT4' ? 'Move closes' : 'Active clock expires' : room.phase === 'LAST_STAND_CHOICE' ? 'House game choice closes' : room.phase === 'DUEL_RESULT' ? 'Result display' : 'Invitations close'} /></div>
    {!duel ? ballotBlocksInvites ? null : <><h2>Put your rivalry on the table.</h2><p>Invite a friend for 50–250 chips each. They choose Rock Paper Scissors, Coin Flip, Connect 4, or Bullet Chess. The first accepted challenge takes this slot. Six-round Party may open a second sequential slot if its full deadline fits; contests never overlap.</p>
      {outgoing ? <p className="duel-outgoing" role="status">Waiting for {name(outgoing.defenderId)}: <strong>{chips(outgoing.amount)} chips reserved</strong>. <Countdown deadline={outgoing.deadline} now={now} label="Your invitation expires" /> Declined or expired invitations return your reservation.</p> : <div className="duel-invite-controls"><label htmlFor="duel-rival">Challenge a friend<select id="duel-rival" value={defenderId} disabled={disabled || !eligible || admissionClosed} onChange={event => setTarget(event.target.value)}>{rivals.map(player => <option key={player.id} value={player.id}>{player.name}</option>)}</select></label><div className="bet-chips" role="group" aria-label="Choose duel stake">{[50, 100, 150, 200, 250].map(stake => <button key={stake} className={`bet-chip ${amount === stake ? 'selected-chip' : ''}`} aria-pressed={amount === stake} aria-label={`Duel stake ${stake} chips`} disabled={disabled || !eligible || admissionClosed || stake > (me?.available ?? 0)} onClick={() => setAmount(stake)}>{stake}</button>)}</div><button className="button primary" disabled={disabled || !eligible || admissionClosed || !defenderId || amount > (me?.available ?? 0)} onClick={() => void sendCommand('duel:invite', { defenderId, amount })}>Send Duel Invite <span>{chips(amount)}</span></button></div>}
      {incoming.map(invite => <section key={invite.id} className="duel-incoming" aria-label={`Challenge from ${name(invite.inviterId)}`}><div className="duel-heading"><h3>{name(invite.inviterId)} challenges you.</h3><Countdown deadline={invite.deadline} now={now} label="Invitation expires" /></div><p>{invite.purpose === 'BOUNTY' ? 'Bounty defense · ' : ''}{chips(invite.amount)} chips each · {chips(invite.amount * 2)} chip pot. You choose the game.{invite.purpose === 'BOUNTY' ? ' A qualifying win advances your defense streak; a loss settles your bounty.' : ''}</p><div className="duel-selection"><label htmlFor={`game-${invite.id}`}>Duel game<select id={`game-${invite.id}`} value={game} disabled={disabled || now >= invite.deadline} onChange={event => setGame(event.target.value as DuelGame)}><option value="RPS">Rock Paper Scissors</option><option value="COIN">Coin Flip</option><option value="CONNECT4">Connect 4</option><option value="CHESS">Bullet Chess</option></select></label>{game === 'COIN' && <label htmlFor={`side-${invite.id}`}>Your coin side<select id={`side-${invite.id}`} value={coinSide} disabled={disabled || now >= invite.deadline} onChange={event => setCoinSide(event.target.value as CoinSide)}><option value="HEADS">Heads</option><option value="TAILS">Tails</option></select></label>}<button className="button primary" disabled={disabled || !eligible || now >= invite.deadline || invite.amount > acceptanceFunds} onClick={() => void sendCommand('duel:accept', { game, ...(game === 'COIN' ? { coinSide } : {}) }, { inviteId: invite.id })}>Accept Duel</button><button className="button secondary" disabled={disabled || now >= invite.deadline} onClick={() => void sendCommand('duel:reject', undefined, { inviteId: invite.id })}>Decline Duel</button></div>{invite.amount > acceptanceFunds && <p className="field-hint">You need {chips(invite.amount)} available chips to accept.</p>}</section>)}
      <p className="field-hint">Invitations expire within 8 seconds. One outgoing invitation per player. No accepted duel means the next Blackjack round starts when admission closes.</p>
    </> : <><h2>{duel.game === 'RPS' ? 'Rock. Paper. Scissors.' : duel.game === 'COIN' ? 'Call it in the air.' : duel.game === 'CONNECT4' ? 'Four in a row.' : 'Bullet Chess.'}</h2><p className="duel-matchup"><strong>{name(duel.inviterId)}</strong><span>vs</span><strong>{name(duel.defenderId)}</strong></p>{duel.purpose === 'BOUNTY' && <p className="bounty-duel-note">Bounty defense · target: {name(duel.defenderId)}. The 100-chip duel pot settles separately from the bounty escrow.</p>}{duel.purpose === 'LAST_STAND' ? <p className="last-stand-stakes"><strong>House crown at stake</strong> · no chip wager. A draw keeps the defending House in place.</p> : <p>{chips(duel.amount)} chips each · <strong>{chips(duel.amount * 2)} chip pot</strong></p>}
      {playing && <div className="duel-total-clock"><span>Absolute duel limit</span><Countdown deadline={duel.hardDeadline} now={now} label="Duel hard limit" /></div>}
      {duel.game === 'RPS' ? <><div className="duel-score" aria-label="Duel score"><span>{name(duel.inviterId)} <strong>{duel.scores[duel.inviterId] ?? 0}</strong></span><span>{name(duel.defenderId)} <strong>{duel.scores[duel.defenderId] ?? 0}</strong></span></div>{playing && <><p>Throw {duel.throwNumber} of 5 · first to 3 wins. Each throw lasts 8 seconds; ties use a throw. One missing choice loses that throw; two missing choices draw it.</p><div className="duel-locks" aria-live="polite">{[duel.inviterId, duel.defenderId].map(id => <span key={id}>{name(id)}: <strong>{duel.lockedPlayerIds.includes(id) ? 'Choice locked' : 'Choosing…'}</strong></span>)}</div>{participant ? <div className="rps-choices" role="group" aria-label="Choose your throw">{(['ROCK', 'PAPER', 'SCISSORS'] as const).map(choice => <button key={choice} className={`button ${duel.ownChoice === choice ? 'primary' : 'secondary'}`} aria-pressed={duel.ownChoice === choice} disabled={disabled || now >= duel.deadline || !!duel.ownChoice} onClick={() => void sendCommand('duel:choose', { choice })}>{choice === 'ROCK' ? 'Rock' : choice === 'PAPER' ? 'Paper' : 'Scissors'}</button>)}</div> : <p className="field-hint">You are watching. Choices stay hidden until both players lock or the throw expires.</p>}{duel.ownChoice && <p className="duel-private" role="status">Your locked choice: {duel.ownChoice.toLowerCase()}. Your rival sees only that you locked.</p>}</>}{!!duel.throws.length && <div className="throw-history" aria-label="Revealed throws">{duel.throws.map(item => <div key={item.number}><strong>Throw {item.number}</strong><span>{name(duel.inviterId)}: {item.choices[duel.inviterId]?.toLowerCase() ?? 'no choice'}</span><span>{name(duel.defenderId)}: {item.choices[duel.defenderId]?.toLowerCase() ?? 'no choice'}</span><b>{item.winnerId ? `${name(item.winnerId)} wins` : 'Draw'}</b></div>)}</div>}</> : duel.game === 'COIN' ? <p className="coin-reveal">{name(duel.defenderId)} called {duel.coinSide?.toLowerCase()}. The server flipped <strong>{duel.coinResult?.toLowerCase()}</strong>.</p> : <BoardDuel key={duel.id + (duel.connect4?.moveId ?? duel.chess?.moveId ?? '')} duel={duel} room={room} disabled={disabled} now={now} />}
      {playing && participant && <button className="text-button duel-resign" disabled={disabled} onClick={() => void sendCommand('duel:resign')}>{duel.purpose === 'LAST_STAND' ? 'Resign Last Stand' : 'Resign Duel (forfeit stake)'}</button>}
      {!playing && <div className="duel-summary" role="status"><h3>{duel.winnerId ? `${name(duel.winnerId)} wins the duel.` : 'The duel is a draw.'}</h3><p>{duel.purpose === 'LAST_STAND' ? duel.winnerId === duel.inviterId ? `${name(duel.inviterId)} takes the House crown. Future commissions follow the new House.` : `${name(duel.defenderId)} retains the House crown.` : duel.winnerId ? `${chips(duel.amount * 2)} chips paid to ${name(duel.winnerId)}; ${chips(duel.amount)} chips net profit.` : `${chips(duel.amount)} chips returned to each player.`}</p><p>{duel.reason?.replaceAll('_', ' ')}</p><p className="field-hint">{duel.purpose === 'LAST_STAND' ? 'No chips moved. The room host is unchanged. Blackjack resumes after this result.' : 'Both stakes are settled. A remaining slot may open before Blackjack resumes.'}</p></div>}
    </>}
  </section>;
}

function ChaosCards({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const [swapTarget, setSwapTarget] = useState('');
  const chaos = room.party?.chaos;
  if (!chaos || room.round === 0) return null;
  const mine = chaos.inventories.find(inventory => inventory.playerId === room.viewerId)?.cards ?? [];
  const me = room.players.find(player => player.id === room.viewerId);
  const multiplier = chaos.multipliers.find(item => item.playerId === room.viewerId);
  const twist = chaos.potTwist;
  const handWindow = chaos.handWindow;
  const selectedTarget = chaos.handTargets.includes(swapTarget) ? swapTarget : chaos.handTargets[0] ?? '';
  const name = (id: string) => room.players.find(player => player.id === id)?.name ?? 'Player';
  const rule = (kind: string) => chaos.registry.find(item => item.kind === kind);
  const deadlinePassed = room.deadline !== null && now >= room.deadline;
  return <section className="chaos-panel" aria-label="Chaos cards">
    <div className="duel-heading"><span className="eyebrow">A LITTLE CHAOS IN YOUR CORNER</span><span className="chaos-allowance">{chaos.usedThisRound ? 'Round activation used' : 'One activation this round'}</span></div>
    <h2>Your next move could change the game.</h2><p>After each nonfinal round, players tied in the bottom two positions receive a random card, up to two held cards. Inventories are public. Each player may use one card or Pot Twist opt-in per round.</p>
    <div className="chaos-public" aria-label="Public Chaos inventory">{chaos.inventories.map(inventory => <div key={inventory.playerId}><strong>{name(inventory.playerId)}{inventory.playerId === room.viewerId ? ' (you)' : ''}</strong><span>{inventory.cards.length ? inventory.cards.map(card => rule(card.kind)?.name ?? card.kind).join(' · ') : 'No cards'}</span></div>)}</div>
    {room.phase === 'HAND_CHAOS' && handWindow && <section className="hand-chaos-window" aria-label="Hand movement window"><div className="duel-heading"><h3>Five seconds to change the hands.</h3><Countdown deadline={handWindow.deadline} now={now} label="Hand movement closes" /></div><p>One Hand Swap or Table Turn may move eligible two-card hands before any player acts. Naturals, the dealer, absent players and unfunded hands stay put. Wagers, seats and bluff allowances stay with their owners.</p><p className="field-hint">Eligible hands: {handWindow.eligibleIds.map(name).join(', ') || 'None'}. {handWindow.resolved ? 'A movement has already resolved.' : 'The first legal movement wins this window.'}</p></section>}
    {mine.length ? <div className="chaos-hand">{mine.map(card => {
      const metadata = rule(card.kind);
      const action = chaos.actions.find(item => item.cardId === card.id);
      const reason = disabled ? 'Wait until your connection and current action are confirmed.' : action?.reason ?? 'This card is unavailable.';
      return <article className="chaos-card" key={card.id} aria-label={`${metadata?.name ?? card.kind} card`}><span className="eyebrow">CHAOS CARD</span><h3>{metadata?.name ?? card.kind}</h3><p>{metadata?.effect}</p><small>{metadata?.window}</small>{card.kind === 'EMERGENCY_FUND' && <p className="chaos-funding">Current funded award: <strong>{chips(chaos.emergencyAmount)} chips</strong>{chaos.emergencyUsed ? ' · already used this match' : ' · once per match'}</p>}{card.kind === 'HAND_SWAP' && <label className="chaos-target" htmlFor={`swap-${card.id}`}>Hand to swap with<select id={`swap-${card.id}`} value={selectedTarget} disabled={disabled || !action?.eligible || !chaos.handTargets.length} onChange={event => setSwapTarget(event.target.value)}>{chaos.handTargets.length ? chaos.handTargets.map(id => <option key={id} value={id}>{name(id)}</option>) : <option value="">No eligible hand</option>}</select></label>}<p className={`chaos-reason ${action?.eligible ? 'chaos-ready' : ''}`} role="status">{reason}</p><button className="button secondary" disabled={disabled || deadlinePassed || !action?.eligible || (card.kind === 'HAND_SWAP' && !selectedTarget)} onClick={() => void sendCommand('chaos:activate', { cardId: card.id, ...(card.kind === 'HAND_SWAP' ? { targetId: selectedTarget } : {}) })}>Play {metadata?.name ?? card.kind}</button></article>;
    })}</div> : <p className="field-hint chaos-empty">No cards in your hand. Earn a card at a nonfinal round settlement if you finish in the bottom two positions, including ties.</p>}
    {multiplier && <p className="chaos-multiplier" role="status">Your funded Blackjack wager: <strong>{chips(me?.wager ?? 0)} chips</strong> · {chips(multiplier.base)} × {multiplier.factor} from {rule(multiplier.source)?.name}. Your card or opt-in remains used if you withdraw or replace this wager.</p>}
    {twist && twist.status !== 'closed' && <section className="pot-twist" aria-label="Pot Twist window"><div className="duel-heading"><h3>{twist.status === 'pending' ? 'Pot Twist is queued.' : 'Five seconds. Your choice.'}</h3>{twist.status === 'open' && <Countdown deadline={twist.deadline} now={now} label="Pot Twist closes" />}</div><p>{name(twist.ownerId)} opened Pot Twist. After ordinary betting closes, eligible players have 5 seconds to double their existing wager with their own chips. Participation is optional; normal payouts apply to the funded wager.</p><p>{twist.optedInIds.length ? `Opted in: ${twist.optedInIds.map(name).join(', ')}.` : 'No players opted in yet.'}</p>{twist.status === 'open' ? <><p className="chaos-reason" role="status">{disabled ? 'Wait for the connection to be restored.' : chaos.optInReason}</p><button className="button primary" disabled={disabled || !chaos.optInEligible || (twist.deadline !== null && now >= twist.deadline)} onClick={() => void sendCommand('chaos:optin')}>Double My Wager</button><p className="field-hint">Opting in uses your round activation. The owner may opt into their own Pot Twist. Extra stakes must be fully available; multipliers cannot stack.</p></> : <p className="field-hint">The opt-in button appears when betting closes. Place your base wager before then.</p>}</section>}
    <details className="chaos-rules"><summary>Chaos card rules and legal windows</summary>{chaos.registry.map(item => <div key={item.kind}><h3>{item.name}</h3><p>{item.effect}</p><small>{item.window}</small></div>)}<p>Cards and activation allowances remain consumed after a successful activation, even if you later withdraw or replace an affected wager. Failed actions consume nothing. A multiplied wager may reach 750 chips; all extra stake comes from the player. Emergency Fund draws only from the finite bonus reserve and can be used once per match. Hand Swap and Table Turn share one five-second window before turns; natural hands and dealer cards never move. Second Chance replaces only your latest ordinary Hit while your hand remains below 21. It cannot undo a bust, 21 or a challenged draw. Discarded cards remain consumed.</p></details>
  </section>;
}

function DiscardedCards({ room }: { room: RoomView }) {
  if (!room.discarded.length) return null;
  return <section className="discarded-cards" aria-label="Consumed redraw cards"><h2>Second Chance discards</h2><p>These public cards left a hand and remain consumed. They cannot be drawn again.</p><div className="cards">{room.discarded.map(card => <PlayingCard key={card.id} card={card} />)}</div></section>;
}

function PartyBank({ room }: { room: RoomView }) {
  const party = room.party;
  if (!party) return null;
  const house = room.players.find(player => player.id === party.houseId);
  return <section className="party-bank" aria-label="Party funds"><div><span className="eyebrow">♛ HOUSE</span><strong>{house?.name ?? (party.auction.status === 'open' ? 'Auction in progress' : 'No House')}</strong><small>Separate from host and neutral dealer</small>{house && <small>House since round {party.houseSinceRound}; {room.round > party.houseSinceRound ? 'completed-round tenure earned' : 'complete a round before an overthrow'}</small>}</div><div><span className="eyebrow">FUNDED VAULT</span><strong>{chips(party.vault)} <small>chips</small></strong><small>Shared equally at match end</small></div><div><span className="eyebrow">BONUS RESERVE</span><strong>{chips(party.bonusReserve)} <small>/ {chips(party.initialBonusReserve)}</small></strong><small>Separate funding; unused chips are not winnings</small></div></section>;
}

function RoundPayouts({ room }: { room: RoomView }) {
  if (room.phase !== 'ROUND_RESULT' || !room.party || !room.roundPayouts.length) return null;
  const house = room.players.find(player => player.id === room.party?.houseId);
  return <section className="round-payouts" aria-label="Round payouts"><h2>Blackjack paid in full.</h2>{room.roundPayouts.map(payout => <div className="payout-row" key={payout.playerId}><strong>{room.players.find(player => player.id === payout.playerId)?.name}</strong><span>{chips(payout.returned)} returned <small>({payout.profit >= 0 ? '+' : ''}{chips(payout.profit)} profit)</small></span><span className="commission">{payout.houseCommission ? `+${chips(payout.houseCommission)} bank-funded commission to ${house?.name ?? 'the House'}` : 'No House commission'}</span></div>)}<p className="field-hint">The dealer bank pays House commissions separately: 3% of eligible positive profit, rounded down; 50 chips maximum per round in seat order. Your payout is never reduced.</p></section>;
}

function VaultDistribution({ room }: { room: RoomView }) {
  if (!room.party) return null;
  const payouts = room.party.transfers.filter(transfer => transfer.kind === 'vault_distribution');
  return <section className="vault-distribution" aria-label="Final Vault distribution"><span className="eyebrow">THE VAULT IS SETTLED</span><h2>{chips(payouts.reduce((sum, payout) => sum + payout.amount, 0))} chips shared</h2><p>All original participants receive equal shares, including absent players. Any extra chips follow original seat order. These shares are included in final balances.</p>{payouts.map(payout => <div className="payout-row" key={payout.id}><strong>{room.players.find(player => player.id === payout.to)?.name ?? 'Original participant'}</strong><span>+{chips(payout.amount)} chips</span></div>)}<p className="field-hint">Unused bonus reserve: {chips(room.party.bonusReserve)} chips. This is not added to player winnings.</p></section>;
}

function Table({ room, disabled, now }: { room: RoomView; disabled: boolean; now: number }) {
  const me = room.players.find(player => player.id === room.viewerId);
  return <main className="table-page"><div className="table-titlebar"><div><span className="eyebrow">{room.mode === 'PARTY' ? 'PARTY BLACKJACK' : 'CLASSIC BLACKJACK'}</span><h1>{phaseNames[room.phase]}</h1></div><div className="round-status"><span>{room.round === 0 ? <>BEFORE THE <strong>FIRST ROUND</strong></> : <>ROUND <strong>{room.round}</strong><small>/ {room.roundLimit}</small></>}</span><Countdown deadline={room.deadline} now={now} label={phaseNames[room.phase]} /></div></div>
    {room.recoveryDeadline && <div className="recovery-note" role="status">Waiting for more players to reconnect. Committed wagers still settle.<Countdown deadline={room.recoveryDeadline} now={now} label="Recovery window" /></div>}
    <PartyBank room={room} /><div className="table-layout"><div className="game-column"><HouseAuction room={room} disabled={disabled} now={now} /><BountyBoard room={room} disabled={disabled} now={now} /><SocialDuel key={room.party?.social?.id} room={room} disabled={disabled} now={now} /><section className="felt-table" aria-label="Blackjack table"><div className="felt-border" /><div className="dealer-area"><span className="dealer-label">THE DEALER <span>STANDS ON ALL 17s</span></span><div className="dealer-hand cards">{room.dealer.length ? room.dealer.map((card, index) => <PlayingCard card={card} key={card?.id ?? `hidden-${index}`} />) : <><div className="empty-card-outline" /><div className="empty-card-outline" /></>}{room.dealerValue && <span className="dealer-total">{room.dealerValue.bust ? 'BUST' : room.dealerValue.natural ? 'BLACKJACK' : room.dealerValue.total}</span>}</div></div><div className="felt-brand" aria-hidden="true"><span>♠</span> BLUFF HOUSE <small>BLACKJACK PAYS 3 TO 2</small></div><div className="player-grid">{room.players.map(player => <PlayerSeat key={player.id} player={player} room={room} />)}</div></section><DiscardedCards room={room} /><BluffEvent room={room} disabled={disabled} now={now} /><RoundPayouts room={room} /><ChaosCards room={room} disabled={disabled} now={now} /><ActionPanel room={room} me={me} disabled={disabled} now={now} /></div><aside className="table-rail"><Standings room={room} /><DuelStats room={room} /><EventFeed room={room} /><div className="rail-footnote">PLAY YOUR CARDS.<br /><span>Read your friends.</span></div></aside></div>
  </main>;
}

function Results({ room, disabled }: { room: RoomView; disabled: boolean }) {
  const results = room.results;
  if (!results) return <main className="results-page"><h1>Settling the table…</h1></main>;
  const winners = results.standings.filter(player => results.winners.includes(player.id));
  return <main className="results-page"><span className="eyebrow">{results.reason ? 'MATCH ENDED EARLY' : 'THE FINAL RECKONING'}</span><div className="winner-crown" aria-hidden="true">♛</div><h1>{winners.map(player => player.name).join(' & ')}<br /><em>{winners.length > 1 ? 'share the crown.' : 'takes the crown.'}</em></h1>{results.reason && <p className="muted">{results.reason}</p>}<p className="result-intro">Scheduled for {room.roundLimit} rounds. Final round: {room.round}. The scores are settled.</p><div className="results-board"><div className="result-row result-table-heading"><span>PLACE</span><span>PLAYER</span><span>BLUFF W / L</span><span>FINAL CHIPS</span></div>{results.standings.map((player, index) => <div className={`result-row ${results.winners.includes(player.id) ? 'winner-row' : ''}`} key={player.id}><strong>{results.winners.includes(player.id) ? '♛' : index + 1}</strong><span>{player.name}{player.id === room.viewerId && <small>YOU</small>}</span><span>{player.bluffWins} / {player.bluffLosses}</span><strong>{chips(player.balance)}</strong></div>)}</div><VaultDistribution room={room} /><BountyBoard room={room} disabled={disabled} now={room.serverTime} /><OverthrowHistory room={room} /><DuelStats room={room} /><div className="biggest-bluff"><span className="eyebrow">BIGGEST BLUFF</span>{results.biggestBluff ? <p>{results.standings.find(player => player.id === results.biggestBluff?.winnerId)?.name ?? 'The winner'} won {chips(results.biggestBluff.pot ?? results.biggestBluff.amount * 2)} chips against {results.standings.find(player => player.id === (results.biggestBluff?.winnerId === results.biggestBluff?.claimantId ? results.biggestBluff?.challengerId : results.biggestBluff?.claimantId))?.name ?? 'their rival'}.<br /><small>{chips(results.biggestBluff.amount)} chip profit · earliest challenge wins equal-pot ties</small></p> : <p>No bluff challenges this match.</p>}</div><button className="button primary results-return" disabled={disabled} onClick={() => void sendCommand('results:return')}>Return to Lobby <span aria-hidden="true">↗</span></button><p className="fine-print">Same room. Fresh stacks. One more chance.</p></main>;
}

function ConnectionOverlay({ state }: { state: ConnectionState }) {
  if (!['reconnecting', 'replaced', 'lost'].includes(state.status)) return null;
  const recovery = state.status === 'reconnecting';
  return <div className="connection-overlay"><div className="connection-card" role="alert"><span className={recovery ? 'connection-spinner' : 'connection-symbol'} aria-hidden="true">{recovery ? '' : '♠'}</span><h2>{recovery ? 'Reconnecting to Bluff House…' : state.status === 'replaced' ? 'Your seat moved tabs.' : 'This table has closed.'}</h2><p>{recovery ? 'Restoring your seat and the latest table. Your committed wagers continue to resolve.' : state.error}</p>{!recovery && <button className="button primary full-width" onClick={returnToMenu}>Return to Menu</button>}</div></div>;
}

export default function App() {
  const state = useSyncExternalStore(subscribe, getSnapshot);
  const [now, setNow] = useState(Date.now());
  const [confirmLeave, setConfirmLeave] = useState(false);
  useEffect(() => { void initializeConnection(); }, []);
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 250); return () => window.clearInterval(timer); }, []);
  const room = state.room;
  const disabled = state.status !== 'connected' || !!state.pending;
  return <><a className="skip-link" href="#app-main">Skip to game</a><div id="app-main">{room ? <><RoomHeader room={room} onLeave={() => { if (room.phase === 'LOBBY' || room.phase === 'RESULTS') void sendCommand('room:leave'); else setConfirmLeave(true); }} />{room.phase === 'LOBBY' ? <Lobby room={room} disabled={disabled} /> : room.phase === 'RESULTS' ? <Results room={room} disabled={disabled} /> : <Table room={room} disabled={disabled} now={Math.max(now + state.clockOffset, room.serverTime)} />}<Reactions key={room.instanceId} state={state} disabled={disabled} /></> : <Menu state={state} />}</div>{room && state.error && state.status === 'connected' && <div className="error-toast" role="alert"><span>{state.error}</span><button className="icon-button" aria-label="Dismiss message" onClick={clearError}>×</button></div>}{state.pending && <div className="pending-indicator" role="status">Confirming your action…</div>}<ConnectionOverlay state={state} />{confirmLeave && <Modal title="Leave this match?" onClose={() => setConfirmLeave(false)}><p className="muted">Your submitted and committed wagers will still settle. Leaving gives up your right to return to this match.</p><div className="dialog-actions"><button className="button secondary" onClick={() => setConfirmLeave(false)}>Stay at the table</button><button className="button danger" disabled={disabled} onClick={async () => { if (await sendCommand('room:leave')) setConfirmLeave(false); }}>Leave Match</button></div></Modal>}</>;
}
